36	interface Candidate {
37	    playerId: number;
38	    goalie: boolean;
39	    played: number;
40	    average: number;
41	    age: number | null;
42	}
43	
44	const sum = (values: number[]) => values.reduce((acc, value) => acc + value, 0);
45	
46	const diffTuple = (
47	    teamAIds: number[],
48	    teamBIds: number[],
49	    byPlayerId: Map<number, Candidate>,
50	    unknownAgeValue: number,
51	) => {
52	    const read = (playerId: number) => {
53	        const candidate = byPlayerId.get(playerId);
54	        if (!candidate) {
55	            throw new Error(`Missing candidate for player ${playerId}`);
56	        }
57	        return candidate;
58	    };
59	    const teamA = teamAIds.map(read);
60	    const teamB = teamBIds.map(read);
61	
62	    const diffGoalies =
63	        sum(teamA.map((player) => (player.goalie ? 1 : 0))) -
64	        sum(teamB.map((player) => (player.goalie ? 1 : 0)));
65	    const diffAverage =
66	        sum(teamA.map((player) => player.average)) -
67	        sum(teamB.map((player) => player.average));
68	    const diffUnknownAge =
69	        sum(teamA.map((player) => (player.age === null ? 1 : 0))) -
70	        sum(teamB.map((player) => (player.age === null ? 1 : 0)));
71	    const diffAge =
72	        sum(teamA.map((player) => player.age ?? unknownAgeValue)) -
73	        sum(teamB.map((player) => player.age ?? unknownAgeValue));
74	
75	    return [
76	        Math.abs(diffGoalies),
77	        Math.abs(diffAverage),
78	        Math.abs(diffUnknownAge),
79	        Math.abs(diffAge),
80	    ];
81	};
82	
83	const compareTuple = (left: number[], right: number[]) => {
84	    const maxLength = Math.max(left.length, right.length);
85	    for (let index = 0; index < maxLength; index++) {
86	        const l = left[index] ?? 0;
87	        const r = right[index] ?? 0;
88	        if (Math.abs(l - r) <= 1e-9) continue;
89	        return l < r ? -1 : 1;
90	    }
91	    return 0;
92	};
93	
94	const uniqueSplits = (playerIdsInOrder: number[]) => {
95	    if (playerIdsInOrder.length % 2 !== 0 || playerIdsInOrder.length < 2)
96	        return [] as { teamA: number[]; teamB: number[] }[];
97	
98	    const teamSize = playerIdsInOrder.length / 2;
99	    const first = playerIdsInOrder[0];
100	    const remaining = playerIdsInOrder.slice(1);
101	    const result: { teamA: number[]; teamB: number[] }[] = [];
102	
103	    const walk = (start: number, needed: number, prefix: number[]) => {
104	        if (needed === 0) {
105	            const teamA = [first, ...prefix];
106	            const teamASet = new Set(teamA);
107	            const teamB = playerIdsInOrder.filter(
108	                (playerId) => !teamASet.has(playerId),
109	            );
110	            result.push({ teamA, teamB });
111	            return;
112	        }
113	
114	        for (let index = start; index <= remaining.length - needed; index++) {
115	            walk(index + 1, needed - 1, [...prefix, remaining[index]]);
116	        }
117	    };
118	
119	    walk(0, teamSize - 1, []);
120	    return result;
121	};
