5	import type { AuthRole, AuthUserSummary } from '@/types/AuthUser';
6	
7	const MOCK_AUTH_COOKIE = 'mock-auth-state';
8	const MOCK_AUTH_USER_COOKIE = 'mock-auth-user';
9	
10	const mockUserDefaults = {
11	    user: {
12	        name: 'Test User',
13	        email: 'testuser@example.com',
14	        playerId: 1,
15	        role: 'user' as const,
16	    },
