25	const parseCookieHeader = (
26	    cookieHeader: string | null,
27	): Record<string, string> => {
28	    if (!cookieHeader) return {};
29	
30	    return cookieHeader
31	        .split(';')
32	        .reduce<Record<string, string>>((acc, cookie) => {
33	            const trimmed = cookie.trim();
34	            if (!trimmed) return acc;
35	            const [name, ...rest] = trimmed.split('=');
36	            if (!name) return acc;
37	            acc[name] = decodeURIComponent(rest.join('='));
38	            return acc;
39	        }, {});
40	};
41	
42	const getMockAuthUserFromCookie = (
43	    cookieHeader: string | null,
44	): Partial<AuthUserSummary> | null => {
45	    const cookies = parseCookieHeader(cookieHeader);
46	    const rawValue = cookies[MOCK_AUTH_USER_COOKIE];
47	    if (!rawValue) return null;
48	
49	    try {
50	        const parsed = JSON.parse(rawValue) as Partial<AuthUserSummary> | null;
51	        return parsed ?? null;
52	    } catch {
53	        return null;
54	    }
55	};
